Input: {"question": "What is the medium of \"The English Patient\"?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0181-c0c498696702:d00", "start": 0, "end": 76, "text": "The English Patient The English Patient is a 1992 novel by Michael Ondaatje."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0181-c0c498696702:d00", "start": 77, "end": 198, "text": "The book follows four dissimilar people brought together at an Italian villa during the Italian Campaign of World War II."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0181-c0c498696702:d00", "start": 199, "end": 381, "text": "The four main characters are: an unrecognisably burned man — the eponymous patient, presumed to be English; his Canadian Army nurse, a Sikh British Army sapper, and a Canadian thief."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0181-c0c498696702:d00", "start": 382, "end": 595, "text": "The story occurs during the North African Campaign and centres on the incremental revelations of the patient's actions prior to his injuries, and the emotional effects of these revelations on the other characters."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0181-c0c498696702:d00", "start": 596, "end": 612, "text": "The book won the"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0181-c0c498696702:d01", "start": 0, "end": 12, "text": "spectacles ."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0181-c0c498696702:d01", "start": 13, "end": 32, "text": "Left-handed catch ."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0181-c0c498696702:d01", "start": 33, "end": 52, "text": "Left-handed poems ."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0181-c0c498696702:d01", "start": 53, "end": 139, "text": "A novel that comes from the left hand of history , out of the sinister heart of fire ."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0181-c0c498696702:d01", "start": 140, "end": 276, "text": "Source : Stephen Scobie , `` The Reading Lesson : Michael Ondaatje and the Patients of Desire , '' in Essays on Canadian Writing , Vol ."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0181-c0c498696702:d01", "start": 277, "end": 300, "text": "53 , Summer 1994 , pp ."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0181-c0c498696702:d01", "start": 301, "end": 309, "text": "92-106 ."}, "D2S8": {"document_number": 2, "doc_id": "ramdocs-0181-c0c498696702:d01", "start": 310, "end": 385, "text": "Sources Bemrose , John , Review of The English Patient , in Maclean , Vol ."}, "D2S9": {"document_number": 2, "doc_id": "ramdocs-0181-c0c498696702:d01", "start": 386, "end": 396, "text": "105 , No ."}, "D2S10": {"document_number": 2, "doc_id": "ramdocs-0181-c0c498696702:d01", "start": 397, "end": 424, "text": "42 , October 19 , 1992 , p."}, "D2S11": {"document_number": 2, "doc_id": "ramdocs-0181-c0c498696702:d01", "start": 425, "end": 429, "text": "71 ."}, "D2S12": {"document_number": 2, "doc_id": "ramdocs-0181-c0c498696702:d01", "start": 430, "end": 464, "text": "Novak , Amy , `` Textual Hauntings"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0181-c0c498696702:d02", "start": 0, "end": 61, "text": "The English Patient is a 1992 video game by Michael Ondaatje."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0181-c0c498696702:d02", "start": 62, "end": 187, "text": "The game follows four dissimilar characters brought together at an Italian villa during the Italian Campaign of World War II."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0181-c0c498696702:d02", "start": 188, "end": 370, "text": "The four main characters are: an unrecognisably burned man — the eponymous patient, presumed to be English; his Canadian Army nurse, a Sikh British Army sapper, and a Canadian thief."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0181-c0c498696702:d02", "start": 371, "end": 584, "text": "The story occurs during the North African Campaign and centres on the incremental revelations of the patient's actions prior to his injuries, and the emotional effects of these revelations on the other characters."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0181-c0c498696702:d02", "start": 585, "end": 668, "text": "The game won several awards for its innovative storytelling and immersive gameplay."}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0181-c0c498696702:d03", "start": 0, "end": 11, "text": "spectacles."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0181-c0c498696702:d03", "start": 12, "end": 30, "text": "Left-handed catch."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0181-c0c498696702:d03", "start": 31, "end": 49, "text": "Left-handed poems."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0181-c0c498696702:d03", "start": 50, "end": 133, "text": "A film that comes from the left hand of history, out of the sinister heart of fire."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0181-c0c498696702:d03", "start": 134, "end": 266, "text": "Source : Stephen Scobie, `` The Reading Lesson : Michael Ondaatje and the Patients of Desire, '' in Essays on Canadian Writing, Vol."}, "D4S6": {"document_number": 4, "doc_id": "ramdocs-0181-c0c498696702:d03", "start": 267, "end": 287, "text": "53, Summer 1994, pp."}, "D4S7": {"document_number": 4, "doc_id": "ramdocs-0181-c0c498696702:d03", "start": 288, "end": 295, "text": "92-106."}, "D4S8": {"document_number": 4, "doc_id": "ramdocs-0181-c0c498696702:d03", "start": 296, "end": 366, "text": "Sources Bemrose, John, Review of The English Patient, in Maclean, Vol."}, "D4S9": {"document_number": 4, "doc_id": "ramdocs-0181-c0c498696702:d03", "start": 367, "end": 375, "text": "105, No."}, "D4S10": {"document_number": 4, "doc_id": "ramdocs-0181-c0c498696702:d03", "start": 376, "end": 400, "text": "42, October 19, 1992, p."}, "D4S11": {"document_number": 4, "doc_id": "ramdocs-0181-c0c498696702:d03", "start": 401, "end": 404, "text": "71."}, "D4S12": {"document_number": 4, "doc_id": "ramdocs-0181-c0c498696702:d03", "start": 405, "end": 495, "text": "Novak, Amy, `` Textual Hauntings in The English Patient, '' in The Antigonish Review, Vol."}, "D4S13": {"document_number": 4, "doc_id": "ramdocs-0181-c0c498696702:d03", "start": 496, "end": 521, "text": "115/116, Winter 1998, pp."}, "D4S14": {"document_number": 4, "doc_id": "ramdocs-0181-c0c498696702:d03", "start": 522, "end": 529, "text": "144-53."}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0181-c0c498696702:d04", "start": 0, "end": 45, "text": "Best Supporting Actress for Juliette Binoche."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0181-c0c498696702:d04", "start": 46, "end": 161, "text": "Ralph Fiennes, playing the titular character, and Kristin Scott Thomas were Oscar-nominated for their performances."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0181-c0c498696702:d04", "start": 162, "end": 220, "text": "The film also won five BAFTA Awards and two Golden Globes."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0181-c0c498696702:d04", "start": 221, "end": 328, "text": "The British Film Institute ranked \"The English Patient\" the 55th greatest British film of the 20th century."}, "D5S5": {"document_number": 5, "doc_id": "ramdocs-0181-c0c498696702:d04", "start": 329, "end": 631, "text": "In the final days of the Italian Campaign of World War II, Hana, a French-Canadian nurse of the Royal Canadian Army Medical Corps, obtains permission from her unit to move into a bombed-out Italian monastery, to look after a dying, critically burned man who speaks English but cannot remember his name."}, "D6S1": {"document_number": 6, "doc_id": "ramdocs-0181-c0c498696702:d05", "start": 0, "end": 102, "text": "audio edition of The English Patient , narrated by Michael York , was issued by Random House in 1993 ."}, "D6S2": {"document_number": 6, "doc_id": "ramdocs-0181-c0c498696702:d05", "start": 103, "end": 197, "text": "A film version of The English Patient , directed by Anthony Minghella , was released in 1996 ."}, "D6S3": {"document_number": 6, "doc_id": "ramdocs-0181-c0c498696702:d05", "start": 198, "end": 356, "text": "It won several Academy Awards , including Best Picture , Best Director , and Best Supporting Actress for Juliette Binoche , who played the character of Hana ."}, "D6S4": {"document_number": 6, "doc_id": "ramdocs-0181-c0c498696702:d05", "start": 357, "end": 415, "text": "Chapter 7 : In Situ Kip was the second son in his family ."}, "D6S5": {"document_number": 6, "doc_id": "ramdocs-0181-c0c498696702:d05", "start": 416, "end": 522, "text": "Although it was traditional for the second son to become a doctor , he enlisted in a Sikh regiment instead"}}, "original_cards": [{"doc_id": "ramdocs-0181-c0c498696702:d02", "card_id": "ramdocs-0181-c0c498696702:d02:c0", "entity": "The English Patient", "scope": "medium", "claim": "The English Patient is a 1992 video game by Michael Ondaatje.", "answer": "video game", "quote": "The English Patient is a 1992 video game by Michael Ondaatje.", "original_document_number": 3}, {"doc_id": "ramdocs-0181-c0c498696702:d05", "card_id": "ramdocs-0181-c0c498696702:d05:c0", "entity": "The English Patient", "scope": "medium", "claim": "The English Patient has an audio edition narrated by Michael York issued by Random House in 1993.", "answer": "audio edition", "quote": "audio edition of The English Patient , narrated by Michael York , was issued by Random House in 1993 .", "original_document_number": 6}, {"doc_id": "ramdocs-0181-c0c498696702:d05", "card_id": "ramdocs-0181-c0c498696702:d05:c1", "entity": "The English Patient", "scope": "medium", "claim": "A film version of The English Patient directed by Anthony Minghella was released in 1996.", "answer": "film", "quote": "A film version of The English Patient , directed by Anthony Minghella , was released in 1996 .", "original_document_number": 6}], "current_answers": ["novel", "video game", "film", "audio edition"], "candidate_answers": [{"candidate_id": "R0", "answer": "novel", "origin